    "kind": "tr",
    "id": "TR-TAPE-EDGE-001",
    "before": {
      "contentField": "description",
      "content": "Datasette.Tick() enforces 32,000-cycle motor ramp (MOTOR_DELAY=32000, datasette/datasette.c:62) before TryReadNextPulse delivers pulses. Ramp only activates when Tick() is used as timing. Motor off resets ramp.",
      "status": "closed",
      "acceptanceCriteria": []
    },
    "proposed": {
      "contentField": "description",
      "content": "Represent datasette startup and delayed motor-stop state in emulated-clock units, preserving pinned VICE alarm scheduling and event order. Preserve pending alarms, cancel a pending stop when motor is re-enabled before the stop executes, and distinguish motor control input from the running-motor state. The observable timing contract must not depend on whether a particular managed Tick method has already been called.",
      "status": "pending",
      "acceptanceCriteria": [
        {
          "id": "ac-01",
          "text": "Assert the native startup schedule at t+32000 from a stopped motor with no pending alarm, and assert that a pending alarm is not overwritten by the start helper.",
          "isSatisfied": false
        },
        {
          "id": "ac-02",
          "text": "Assert motor-off at t on a running motor retains running state before the stop executes at t+32000, and that repeated motor-off preserves the first deadline.",
          "isSatisfied": false
        },
        {
          "id": "ac-03",
          "text": "Assert motor-on before pending stop execution clears the stop deadline and preserves running state without another startup delay; assert motor-on after an executed stop schedules a new native startup alarm.",
          "isSatisfied": false
        },
        {
          "id": "ac-04",
          "text": "Compare ordered pulse and motor-state traces at deadline-1, deadline, and deadline+1 using fixed clock/control/alarm order. Do not use a first-Tick bypass or an unconditional off/on ramp reset as a substitute for native behavior.",
          "isSatisfied": false
        }
      ]
    },
